--
-- Table structure for table `domicilio`
--

DROP TABLE IF EXISTS `domicilio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `domicilio` (
  `id` int NOT NULL AUTO_INCREMENT,
  `calle` varchar(128) NOT NULL,
  `numero` varchar(200) NOT NULL,
  `numero_tipo` varchar(16) DEFAULT NULL,
  `cp` varchar(4) DEFAULT NULL,
  `ciudad` varchar(110) DEFAULT NULL,
  `provincia` varchar(8) DEFAULT NULL,
  `pais` varchar(25) DEFAULT NULL,
  `barrio_id` int DEFAULT NULL,
  `distrito_id` int DEFAULT NULL,
  `contribuyente_id` int DEFAULT NULL,
  `rubro_id` int DEFAULT NULL,
  `calle_raw` varchar(128) DEFAULT NULL,
  `calle_normalizada` varchar(128) DEFAULT NULL,
  `calle_key` varchar(128) DEFAULT NULL,
  `calle_catalogo_id` int DEFAULT NULL,
  `calle_norm_status` varchar(32) NOT NULL,
  `calle_norm_score` float DEFAULT NULL,
  `calle_norm_error` varchar(255) DEFAULT NULL,
  `calle_norm_updated_at` datetime DEFAULT NULL,
  `esquina_raw` varchar(255) DEFAULT NULL,
  `esquina_catalogo_id` int DEFAULT NULL,
  `esquina_normalizada` varchar(255) DEFAULT NULL,
  `esquina_norm_status` varchar(16) DEFAULT NULL,
  `esquina_norm_score` float DEFAULT NULL,
  `esquina_norm_error` varchar(255) DEFAULT NULL,
  `esquina_norm_updated_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_domicilio_barrio_id` (`barrio_id`),
  KEY `ix_domicilio_calle` (`calle`),
  KEY `ix_domicilio_calle_catalogo_id` (`calle_catalogo_id`),
  KEY `ix_domicilio_calle_key` (`calle_key`),
  KEY `ix_domicilio_calle_norm_status` (`calle_norm_status`),
  KEY `ix_domicilio_contribuyente_id` (`contribuyente_id`),
  KEY `ix_domicilio_distrito_id` (`distrito_id`),
  KEY `ix_domicilio_esquina_catalogo_id` (`esquina_catalogo_id`),
  KEY `ix_domicilio_esquina_norm_status` (`esquina_norm_status`),
  KEY `ix_domicilio_numero` (`numero`),
  KEY `ix_domicilio_numero_tipo` (`numero_tipo`),
  KEY `ix_domicilio_rubro_id` (`rubro_id`),
  CONSTRAINT `domicilio_ibfk_1` FOREIGN KEY (`barrio_id`) REFERENCES `barrio` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `domicilio_ibfk_2` FOREIGN KEY (`calle_catalogo_id`) REFERENCES `calle_catalogo` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `domicilio_ibfk_3` FOREIGN KEY (`contribuyente_id`) REFERENCES `contribuyente` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `domicilio_ibfk_4` FOREIGN KEY (`distrito_id`) REFERENCES `distrito` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `domicilio_ibfk_5` FOREIGN KEY (`esquina_catalogo_id`) REFERENCES `calle_catalogo` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `domicilio_ibfk_6` FOREIGN KEY (`rubro_id`) REFERENCES `rubro` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

