DROP TABLE IF EXISTS `domicilio_geocode`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `domicilio_geocode` (
  `domicilio_id` int NOT NULL,
  `lat` decimal(10,7) DEFAULT NULL,
  `lng` decimal(10,7) DEFAULT NULL,
  `geo_status` enum('PENDING','OK','REVIEW','NO_MATCH','ERROR','NORM_PENDING','GEO_PENDING') NOT NULL,
  `provider` varchar(50) DEFAULT NULL,
  `quality` varchar(30) DEFAULT NULL,
  `score` float DEFAULT NULL,
  `error_msg` varchar(255) DEFAULT NULL,
  `raw_json` json DEFAULT NULL,
  `addr_hash` varchar(40) DEFAULT NULL,
  `source` enum('AUTO','MANUAL','REVERSE') DEFAULT NULL,
  `checked_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `provider_place_id` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`domicilio_id`),
  KEY `ix_domicilio_geocode_deleted_at` (`deleted_at`),
  KEY `ix_domicilio_geocode_geo_status` (`geo_status`),
  CONSTRAINT `domicilio_geocode_ibfk_1` FOREIGN KEY (`domicilio_id`) REFERENCES `domicilio` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
