--
-- Table structure for table `expediente`
--

DROP TABLE IF EXISTS `expediente`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `expediente` (
  `id` int NOT NULL AUTO_INCREMENT,
  `numero_expediente` varchar(6) NOT NULL,
  `fecha_expediente` date DEFAULT NULL,
  `anio` varchar(4) NOT NULL,
  `tipo_expediente` enum('ENVIO_ACTA','RESPUESTA_OFICIO','PRORROGA_NOTIFICACION','OTRO') DEFAULT NULL,
  `comprobacion_id` int DEFAULT NULL,
  `notificacion_id` int DEFAULT NULL,
  `oficio_id` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `prorroga_dias_otorgados` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ex_numero_anio` (`numero_expediente`,`anio`),
  KEY `oficio_id` (`oficio_id`),
  KEY `ix_expediente_anio` (`anio`),
  KEY `ix_expediente_comprobacion_id` (`comprobacion_id`),
  KEY `ix_expediente_fecha_expediente` (`fecha_expediente`),
  KEY `ix_expediente_notificacion_id` (`notificacion_id`),
  KEY `ix_expediente_numero_expediente` (`numero_expediente`),
  KEY `ix_expediente_tipo_expediente` (`tipo_expediente`),
  CONSTRAINT `expediente_ibfk_1` FOREIGN KEY (`comprobacion_id`) REFERENCES `comprobacion` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `expediente_ibfk_2` FOREIGN KEY (`notificacion_id`) REFERENCES `notificacion` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `expediente_ibfk_3` FOREIGN KEY (`oficio_id`) REFERENCES `oficio` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3281 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

