DROP TABLE IF EXISTS `inspeccion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inspeccion` (
  `id` int NOT NULL AUTO_INCREMENT,
  `numero_acta` varchar(6) NOT NULL,
  `anio` int NOT NULL,
  `mes` int NOT NULL,
  `actuacion_id` int NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ai_numero_anio` (`numero_acta`,`anio`),
  UNIQUE KEY `ix_inspeccion_actuacion_id` (`actuacion_id`),
  KEY `ix_inspeccion_anio` (`anio`),
  KEY `ix_inspeccion_mes` (`mes`),
  KEY `ix_inspeccion_numero_acta` (`numero_acta`),
  CONSTRAINT `inspeccion_ibfk_1` FOREIGN KEY (`actuacion_id`) REFERENCES `actuaciones` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1344 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
