--
-- Table structure for table `oficio`
--

DROP TABLE IF EXISTS `oficio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `oficio` (
  `id` int NOT NULL AUTO_INCREMENT,
  `numero_oficio` varchar(30) NOT NULL,
  `anio` int NOT NULL,
  `fecha_oficio` date DEFAULT NULL,
  `causa` varchar(255) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `juzgado_id` int DEFAULT NULL,
  `comprobacion_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_of_numero_anio` (`numero_oficio`,`anio`),
  KEY `ix_oficio_anio` (`anio`),
  KEY `ix_oficio_causa` (`causa`),
  KEY `ix_oficio_comprobacion_id` (`comprobacion_id`),
  KEY `ix_oficio_fecha_oficio` (`fecha_oficio`),
  KEY `ix_oficio_juzgado_id` (`juzgado_id`),
  KEY `ix_oficio_numero_oficio` (`numero_oficio`),
  CONSTRAINT `oficio_ibfk_1` FOREIGN KEY (`comprobacion_id`) REFERENCES `comprobacion` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `oficio_ibfk_2` FOREIGN KEY (`juzgado_id`) REFERENCES `juzgado_catalogo` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1763 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

