--
-- Table structure for table `ruta_item`
--

DROP TABLE IF EXISTS `ruta_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ruta_item` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ruta_trabajo_id` int NOT NULL,
  `ruta_grupo_id` int DEFAULT NULL,
  `iniciador_ruta_id` int NOT NULL,
  `orden_trabajo_id` int DEFAULT NULL,
  `estado_ruta_item` enum('PENDIENTE_ASIGNACION','ASIGNADO','EN_PROCESO','FINALIZADO','NO_REALIZADO','CANCELADO') NOT NULL DEFAULT 'PENDIENTE_ASIGNACION',
  `estado_ejecucion` enum('REALIZADO','NO_REALIZADO') DEFAULT NULL,
  `motivo_no_realizado` enum('LOCAL_CERRADO','INCLEMENCIA_TIEMPO','NO_EXISTE_LOCAL','OTRO') DEFAULT NULL,
  `observaciones_ejecucion` text,
  `actuacion_id` int DEFAULT NULL,
  `ejecutado_por_user_id` int DEFAULT NULL,
  `ejecutado_at` datetime DEFAULT NULL,
  `created_by_user_id` int NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ruta_item_ruta_iniciador` (`ruta_trabajo_id`,`iniciador_ruta_id`),
  KEY `ix_ruta_item_actuacion_id` (`actuacion_id`),
  KEY `ix_ruta_item_created_by_user_id` (`created_by_user_id`),
  KEY `ix_ruta_item_deleted_at` (`deleted_at`),
  KEY `ix_ruta_item_ejecutado_por_user_id` (`ejecutado_por_user_id`),
  KEY `ix_ruta_item_estado_ejecucion` (`estado_ejecucion`),
  KEY `ix_ruta_item_estado_ruta_item` (`estado_ruta_item`),
  KEY `ix_ruta_item_iniciador_ruta_id` (`iniciador_ruta_id`),
  KEY `ix_ruta_item_motivo_no_realizado` (`motivo_no_realizado`),
  KEY `ix_ruta_item_orden_trabajo_id` (`orden_trabajo_id`),
  KEY `ix_ruta_item_ruta_grupo_id` (`ruta_grupo_id`),
  KEY `ix_ruta_item_ruta_trabajo_id` (`ruta_trabajo_id`),
  CONSTRAINT `ruta_item_ibfk_1` FOREIGN KEY (`actuacion_id`) REFERENCES `actuaciones` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `ruta_item_ibfk_2` FOREIGN KEY (`created_by_user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ruta_item_ibfk_3` FOREIGN KEY (`ejecutado_por_user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ruta_item_ibfk_4` FOREIGN KEY (`iniciador_ruta_id`) REFERENCES `iniciador_ruta` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ruta_item_ibfk_5` FOREIGN KEY (`orden_trabajo_id`) REFERENCES `orden_trabajo` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
