--
-- Table structure for table `ruta_pool_dia`
--

DROP TABLE IF EXISTS `ruta_pool_dia`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ruta_pool_dia` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fecha` date NOT NULL,
  `turno_id` int DEFAULT NULL,
  `usuario_id` int NOT NULL,
  `origen_tipo` enum('INICIADOR','ACTUACION_NOTIF','ACTUACION_COMP','RELEVAMIENTO','DENUNCIA','MANUAL') NOT NULL,
  `iniciador_ruta_id` int DEFAULT NULL,
  `actuacion_id` int DEFAULT NULL,
  `domicilio_id` int NOT NULL,
  `distrito_id` int DEFAULT NULL,
  `rubro_id` int DEFAULT NULL,
  `estado` enum('EN_POOL','ASIGNADO_A_RUTA','DESCARTADO') NOT NULL DEFAULT 'EN_POOL',
  `ruta_trabajo_id` int DEFAULT NULL,
  `ruta_item_id` int DEFAULT NULL,
  `observacion` text,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_ruta_pool_dia_fecha` (`fecha`),
  KEY `ix_ruta_pool_dia_turno_id` (`turno_id`),
  KEY `ix_ruta_pool_dia_usuario_id` (`usuario_id`),
  KEY `ix_ruta_pool_dia_origen_tipo` (`origen_tipo`),
  KEY `ix_ruta_pool_dia_iniciador_ruta_id` (`iniciador_ruta_id`),
  KEY `ix_ruta_pool_dia_actuacion_id` (`actuacion_id`),
  KEY `ix_ruta_pool_dia_domicilio_id` (`domicilio_id`),
  KEY `ix_ruta_pool_dia_distrito_id` (`distrito_id`),
  KEY `ix_ruta_pool_dia_rubro_id` (`rubro_id`),
  KEY `ix_ruta_pool_dia_estado` (`estado`),
  KEY `ix_ruta_pool_dia_ruta_trabajo_id` (`ruta_trabajo_id`),
  KEY `ix_ruta_pool_dia_ruta_item_id` (`ruta_item_id`),
  KEY `ix_ruta_pool_dia_deleted_at` (`deleted_at`),
  KEY `ix_ruta_pool_dia_fecha_estado_distrito_rubro` (`fecha`,`estado`,`distrito_id`,`rubro_id`),
  CONSTRAINT `ruta_pool_dia_ibfk_1` FOREIGN KEY (`actuacion_id`) REFERENCES `actuaciones` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `ruta_pool_dia_ibfk_2` FOREIGN KEY (`distrito_id`) REFERENCES `distrito` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `ruta_pool_dia_ibfk_3` FOREIGN KEY (`domicilio_id`) REFERENCES `domicilio` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ruta_pool_dia_ibfk_4` FOREIGN KEY (`iniciador_ruta_id`) REFERENCES `iniciador_ruta` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ruta_pool_dia_ibfk_5` FOREIGN KEY (`rubro_id`) REFERENCES `rubro` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `ruta_pool_dia_ibfk_6` FOREIGN KEY (`ruta_item_id`) REFERENCES `ruta_item` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `ruta_pool_dia_ibfk_7` FOREIGN KEY (`ruta_trabajo_id`) REFERENCES `ruta_trabajo` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `ruta_pool_dia_ibfk_8` FOREIGN KEY (`turno_id`) REFERENCES `turno` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `ruta_pool_dia_ibfk_9` FOREIGN KEY (`usuario_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=994 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
