--
-- Table structure for table `ruta_trabajo`
--

DROP TABLE IF EXISTS `ruta_trabajo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ruta_trabajo` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fecha` date NOT NULL,
  `turno` enum('MANIANA','TARDE') NOT NULL,
  `estado_ruta` enum('BORRADOR','PUBLICADA','EN_CURSO','CERRADA','CANCELADA') NOT NULL DEFAULT 'BORRADOR',
  `numero` smallint NOT NULL DEFAULT '1',
  `observaciones` text,
  `created_by_user_id` int NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ruta_trabajo_fecha_turno_numero` (`fecha`,`turno`,`numero`),
  KEY `ix_ruta_trabajo_created_by_user_id` (`created_by_user_id`),
  KEY `ix_ruta_trabajo_estado_ruta` (`estado_ruta`),
  KEY `ix_ruta_trabajo_fecha` (`fecha`),
  KEY `ix_ruta_trabajo_fecha_turno_estado` (`fecha`,`turno`,`estado_ruta`),
  KEY `ix_ruta_trabajo_turno` (`turno`),
  CONSTRAINT `ruta_trabajo_ibfk_1` FOREIGN KEY (`created_by_user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7901 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

